package io.atlas.modules.auth.service;
import io.atlas.AtlasMod;import io.atlas.modules.auth.AuthModule;import io.atlas.modules.auth.repository.AuthRepository;
import com.google.gson.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.network.chat.Component;
import java.net.URI;import java.net.http.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import org.mindrot.jbcrypt.BCrypt;
/** Network/BCrypt outside tick thread; game DB and live identity changes stay on server thread. */
public final class AuthRecoveryService {
 private final AuthRepository repository=new AuthRepository();private final Map<UUID,Long> last=new HashMap<>();private final Map<UUID,Long> notices=new HashMap<>();
 private final ThreadPoolExecutor executor=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(16),r->{var t=new Thread(r,"atlas-auth-recovery");t.setDaemon(true);return t;});
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(3)).followRedirects(HttpClient.Redirect.NEVER).build();
 private URI endpoint;private String key;
 public void start(){if(io.atlas.modules.lobby.service.DevEnvironment.DEVELOPMENT)return;try{var p=new Properties();try(var in=Files.newInputStream(Path.of("config/atlas-site.properties"))){p.load(in);}if(!p.getProperty("api-url","").trim().equals("http://127.0.0.1:8080")||p.getProperty("key","").trim().length()<43)throw new IllegalArgumentException();endpoint=URI.create("http://127.0.0.1:8080/internal/v1/minecraft/password-recovery/");key=p.getProperty("key").trim();}catch(Exception e){AtlasMod.LOGGER.warn("Recuperação de senha por email indisponível: configuração ausente/inválida.");}}
 public void stop(){executor.shutdownNow();last.clear();notices.clear();}
 private void message(ServerPlayer p,String m){p.sendSystemMessage(Component.literal(m));}
 private boolean ready(ServerPlayer p,boolean authenticated){if(endpoint==null){message(p,"§eRecuperação por email temporariamente indisponível.");return false;}if(authenticated&&!AuthModule.getAuthService().isAuthenticated(p.getUUID())){message(p,"§cFaça login antes de cadastrar ou confirmar email.");return false;}return true;}
 private boolean throttle(ServerPlayer p){long now=System.currentTimeMillis();if(now-last.getOrDefault(p.getUUID(),0L)<5000){message(p,"§eAguarde alguns segundos antes de tentar novamente.");return false;}last.put(p.getUUID(),now);last.entrySet().removeIf(e->now-e.getValue()>600000);return true;}
 public static boolean validEmail(String email){return email!=null&&email.length()<=254&&email.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+");}
 private JsonObject body(UUID player){var b=new JsonObject();b.addProperty("player",player.toString());return b;}
 private HttpResponse<String> post(String path,JsonObject body)throws Exception{return http.send(HttpRequest.newBuilder(endpoint.resolve(path)).timeout(Duration.ofSeconds(8)).header("Content-Type","application/json").header("X-Atlas-Key",key).POST(HttpRequest.BodyPublishers.ofString(body.toString())).build(),HttpResponse.BodyHandlers.ofString());}
 private boolean sameConnection(ServerPlayer original){return original.getServer()!=null&&original.getServer().getPlayerList().getPlayer(original.getUUID())==original;}
 private int submit(ServerPlayer player,String path,JsonObject b,boolean mustBeAuthenticated,String success){if(!throttle(player))return 0;var server=player.getServer();try{executor.execute(()->{int status;try{status=post(path,b).statusCode();}catch(Exception e){status=503;}final int code=status;server.execute(()->{if(!sameConnection(player)||(mustBeAuthenticated&&!AuthModule.getAuthService().isAuthenticated(player.getUUID())))return;message(player,code==200||code==202||code==204?success:code==401?"§cCódigo inválido, expirado ou sem email confirmado. Solicite outro código.":code==429?"§eLimite de tentativas atingido. Aguarde antes de tentar novamente.":"§eServiço de email indisponível. Tente mais tarde.");});});}catch(RejectedExecutionException e){message(player,"§eServiço ocupado. Tente novamente.");return 0;}message(player,"§7Verificando solicitação…");return 1;}
 public int email(ServerPlayer player,String email){if(!ready(player,true))return 0;if(!validEmail(email)){message(player,"§cInforme um email válido, por exemplo: /email cadastrar seu@email.com");return 0;}var b=body(player.getUUID());b.addProperty("email",email);return submit(player,"email/request",b,true,"§aCódigo enviado ao email informado. §eUse /email confirmar <codigo>. §7Vale por 10 minutos; confira o spam.");}
 public int confirmEmail(ServerPlayer player,String code){if(!ready(player,true))return 0;if(!code.matches("[0-9]{8}")){message(player,"§cUse o código de 8 dígitos recebido no email.");return 0;}var b=body(player.getUUID());b.addProperty("code",code);return submit(player,"email/confirm",b,true,"§aEmail de recuperação confirmado! §7Se esquecer sua senha, use /recuperarsenha.");}
 public int request(ServerPlayer player){if(!ready(player,false))return 0;var account=repository.findAccountByPlayerUuid(player.getUUID());if(account.isEmpty()||account.get().premium()){message(player,"§eRecuperação de senha local é destinada às contas registradas com /register.");return 0;}return submit(player,"request",body(player.getUUID()),false,"§aSe houver email confirmado de recuperação ou vínculo anterior no site, enviaremos um código. §7Confira o spam. Use /recuperarsenha confirmar <codigo> <novaSenha> <confirmacao>. Sem email anterior, abra ticket para verificar a titularidade.");}
 public int reset(ServerPlayer player,String code,String password,String confirmation){
  if(!ready(player,false)||!throttle(player))return 0;
  if(!code.matches("[0-9]{8}")||!password.equals(confirmation)||password.length()<8||password.getBytes(StandardCharsets.UTF_8).length>72){message(player,"§cUse código de 8 dígitos e senhas iguais, com pelo menos 8 caracteres e até 72 bytes.");return 0;}
  var account=repository.findAccountByPlayerUuid(player.getUUID());if(account.isEmpty()||account.get().premium()){message(player,"§cEsta conta não possui senha local recuperável.");return 0;}String expected=account.get().passwordHash();var b=body(player.getUUID());b.addProperty("code",code);var server=player.getServer();
  try{executor.execute(()->{int status;String hash=null;try{hash=BCrypt.hashpw(password,BCrypt.gensalt(12));status=post("verify",b).statusCode();}catch(Exception e){status=503;}final String newHash=hash;final int response=status;server.execute(()->{if(!sameConnection(player))return;if(response!=204){message(player,response==401?"§cCódigo inválido, expirado ou já utilizado.":"§eNão foi possível concluir. Tente mais tarde ou solicite outro código.");return;}try{if(!AuthModule.getAuthService().resetPasswordWithVerifiedEmail(player.getUUID(),expected,newHash)){message(player,"§eA conta foi alterada durante a solicitação. Solicite outro código.");return;}player.connection.disconnect(Component.literal("Senha redefinida pelo email. Entre novamente e use /login com a nova senha."));}catch(Exception e){message(player,"§cFalha ao salvar a senha. Solicite outro código e tente novamente.");}});});}catch(RejectedExecutionException e){message(player,"§eServiço ocupado. Tente novamente.");return 0;}message(player,"§7Confirmando recuperação…");return 1;
 }
 public void notifyMissingEmail(ServerPlayer player){if(!readySilently(player)||!AuthModule.getAuthService().isAuthenticated(player.getUUID()))return;long now=System.currentTimeMillis();if(now-notices.getOrDefault(player.getUUID(),0L)<600000)return;notices.put(player.getUUID(),now);notices.entrySet().removeIf(e->now-e.getValue()>3600000);var server=player.getServer();try{executor.execute(()->{boolean missing;try{var response=post("email/status",body(player.getUUID()));if(response.statusCode()!=200)return;missing=!JsonParser.parseString(response.body()).getAsJsonObject().get("configured").getAsBoolean();}catch(Exception e){return;}if(missing)server.execute(()->{if(sameConnection(player)&&AuthModule.getAuthService().isAuthenticated(player.getUUID()))message(player,"§6Proteja sua conta: você ainda não tem email de recuperação confirmado. §eUse /email cadastrar <email> §6e depois /email confirmar <codigo>. Nunca envie sua senha à staff.");});});}catch(RejectedExecutionException ignored){}}
 private boolean readySilently(ServerPlayer p){return endpoint!=null&&!io.atlas.modules.lobby.service.DevEnvironment.DEVELOPMENT;}
}
